function exportPNG(){if(state.view==='2d'){const svg=el('plan').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','1600');svg.setAttribute('height','1200');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.svg-room{stroke:#526d91;stroke-width:.06}.svg-text{font-family:Arial;text-anchor:middle;font-size:.35px;font-weight:650;fill:#294260}.svg-area{fill:#70839c;font-size:.29px;text-anchor:middle}';svg.insertBefore(style,svg.firstChild);const xml=new XMLSerializer().serializeToString(svg);const image=new Image(),url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'}));image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1200;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,1600,1200);context.drawImage(image,0,0);canvas.toBlob(blob=>{if(blob)makeDownload(blob,filename('png'),'image/png');},'image/png');URL.revokeObjectURL(url);};image.onerror=()=>{toast('Não foi possível gerar PNG. Use a exportação SVG.');URL.revokeObjectURL(url);};image.src=url;}else{el('model3d').toBlob(blob=>blob&&makeDownload(blob,filename('png'),'image/png'),'image/png');}}
function showModal(title,html){el('modalTitle').textContent=title;el('modalBody').innerHTML=html;el('modal').classList.remove('hidden');}
