function importJSON(file){if(!file||file.size>3*1024*1024){toast('Arquivo muito grande (máximo 3 MB).');return;}const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(!validProject(p))throw new Error('Estrutura incompatível');p.id=uid();p.name=String(p.name).slice(0,80);p.levels.forEach(l=>{l.name=String(l.name||'Pavimento').slice(0,80);for(const room of l.rooms){room.name=String(room.name||'Ambiente').slice(0,80);room.type=Object.keys(COLORS).includes(room.type)?room.type:'Ambiente';room.color=/^#[0-9a-f]{6}$/i.test(room.color)?room.color:COLORS.Ambiente;for(const key of ['x','y','w','h']){room[key]=clamp(num(room[key]),key==='w'||key==='h'?.1:0,200);}}});state.project=sanitizeProject(p);state.history=[];state.future=[];state.activeLevel=0;state.selected=null;fit();refreshAll(true);saveLocal();toast('Projeto importado com sucesso.');}catch(e){toast('JSON inválido: '+e.message);}};r.readAsText(file);}
async function api(action,method='GET',payload=null){const opts={method,credentials:'same-origin',headers:{Accept:'application/json'}};if(method!=='GET'){opts.headers['Content-Type']='application/json';if(state.server.csrf)opts.headers['X-CSRF-Token']=state.server.csrf;opts.body=JSON.stringify(payload||{});}const response=await fetch('api.php?action='+encodeURIComponent(action.split('&')[0])+(action.includes('&')?'&'+action.split('&').slice(1).join('&'):''),opts);const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error||'Erro de conexão');return data;}
